{
  "description": "Asks before a file-editing tool writes a Claude Code settings file, where an unreviewed edit changes the harness itself. Shell writes and files rendered into place by other programs are not seen. The register.tsx module draws the live per-category context breakdown as a pane or a band above the prompt.",
  "modules": ["./register.tsx"],
  "hooks": {
    "SessionStart": [
      {
        "matcher": "startup|resume|clear|fork",
        "hooks": [
          {
            "type": "command",
            "command": "sh \"${CLAUDE_PLUGIN_ROOT}/lib/prerequisites.sh\" node-notice /context-budget:check; ${PPID:+exit}; powershell -NoProfile -ExecutionPolicy Bypass -File \"${CLAUDE_PLUGIN_ROOT}/lib/prerequisites.ps1\" node-notice /context-budget:check",
            "timeout": 10,
            "statusMessage": "Checking that node is on PATH..."
          }
        ]
      }
    ],
    "PreToolUse": [
      {
        "matcher": "Write|Edit|NotebookEdit",
        "hooks": [
          {
            "type": "command",
            "command": "node",
            "args": ["${CLAUDE_PLUGIN_ROOT}/hooks/settings-write-ask.mjs"],
            "timeout": 30,
            "statusMessage": "Checking whether this write targets a Claude Code settings surface..."
          }
        ]
      }
    ]
  }
}

